test('addLine can update multiple times', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  let invoice = result.value;

  // Add same SKU twice
  let addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 2 });
  assert.equal(addResult.ok, true);
  invoice = addResult.value;
  assert.equal(invoice.lines[0].qty, 3);

  addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });
  assert.equal(addResult.ok, true);
  invoice = addResult.value;
  assert.equal(invoice.lines[0].qty, 8);
});

test('removeLine can remove from multi-line invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 2 },
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'STICKER', qty: 100 },
    ],
  });

  const invoice = result.value;
  const removeResult = removeLine(invoice, 'LOGO-PACK');

  assert.equal(removeResult.ok, true);
  assert.equal(removeResult.value.lines.length, 2);
  assert.equal(removeResult.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(removeResult.value.lines[1].sku, 'STICKER');
});
